from django.db import migrations, models


def reopen_unfinished_workflows(apps, schema_editor):
    """
    Раньше процесс, однажды получивший статус «Завершён», оставался таким, даже если в него
    добавляли задачи или возвращали их в работу. Приводим статусы в соответствие с задачами.
    """
    WorkflowInstance = apps.get_model('workflows', 'WorkflowInstance')
    for instance in WorkflowInstance.objects.filter(status='COMPLETED'):
        if instance.tasks.exclude(status='DONE').exists():
            instance.status = 'IN_PROGRESS'
            instance.completed_at = None
            instance.save(update_fields=['status', 'completed_at'])


